// Data shape: e.getClass(), e.getMessage(), e.getCause(), e.getStackTrace()
class HierarchyDemo {
    static void unchecked() {
        try {
            Object value = null;
            value.toString();
        } catch (RuntimeException e) {
            // RuntimeException and its subclasses need no throws clause.
            System.out.println(e.getClass().getSimpleName()); // NullPointerException
            System.out.println(e.getMessage());               // may be null
            System.out.println(e.getCause());                 // null unless wrapped
        }
    }

    // A checked type is part of the method contract.
    static void checked() throws java.io.IOException {
        throw new java.io.IOException("disk unavailable");
    }
}

import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;

class CheckedDemo {
    // Checked: every caller must catch IOException or declare it too.
    static String read(Path path) throws IOException {
        return Files.readString(path);
    }

    // Unchecked: no throws clause, and callers are not forced to catch.
    static int parseStars(String text) {
        int stars = Integer.parseInt(text); // NumberFormatException is unchecked
        if (stars < 1 || stars > 5) {
            throw new IllegalArgumentException("stars must be 1..5");
        }
        return stars;
    }

    public static void main(String[] args) {
        try {
            System.out.println(read(Path.of("bookings-sample.csv")).length());
        } catch (IOException e) {
            System.out.println("read failed: " + e.getMessage());
        }
    }
}

