import java.util.Scanner;

class FinallyDemo {
    static void readEmail() {
        Scanner scanner = new Scanner(System.in);
        try {
            System.out.print("customer_email: ");
            String email = scanner.nextLine();
            System.out.println("checking " + email);
            if (email.isBlank()) {
                return; // finally still runs before the return completes
            }
            System.out.println("accepted");
        } finally {
            scanner.close();
            System.out.println("scanner closed");
        }
    }

    // Trap: a return in finally discards the pending exception and earlier return.
    static int broken() {
        try {
            return 1;
        } finally {
            return 2; // Always 2, and any exception from try vanishes.
        }
    }
}

import java.io.BufferedReader;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;

Path file = Path.of("bookings-sample.csv");

// reader is closed before the catch block runs.
try (BufferedReader reader = Files.newBufferedReader(file, StandardCharsets.UTF_8)) {
    String line = reader.readLine();
    while (line != null) {
        System.out.println(line);
        line = reader.readLine();
    }
} catch (IOException e) {
    System.out.println("cannot read " + file + ": " + e.getMessage());
}

// Java 9 form for an effectively final variable declared earlier.
BufferedReader other = Files.newBufferedReader(file);
try (other) {
    System.out.println(other.readLine());
}

import java.io.IOException;

class SuppressedDemo {

    static class FailingClose implements AutoCloseable {
        private final String name;

        FailingClose(String name) {
            this.name = name;
        }

        @Override
        public void close() throws IOException {
            throw new IOException(name + " close failed");
        }
    }

    public static void main(String[] args) {
        try (FailingClose first = new FailingClose("first");
             FailingClose second = new FailingClose("second")) {
            throw new IllegalStateException("body failed");
        } catch (Exception e) {
            System.out.println("primary: " + e); // IllegalStateException
            for (Throwable suppressed : e.getSuppressed()) {
                System.out.println("suppressed: " + suppressed); // second, then first
            }
        }
    }
}

class Stars {
    // throws is part of the contract: callers must handle it or declare it.
    static void validate(int stars) throws IllegalArgumentException {
        if (stars < 1 || stars > 5) {
            // throw ends this path immediately with an object that carries data.
            throw new IllegalArgumentException("stars must be 1..5, got " + stars);
        }
    }

    static String label(int stars) throws Exception {
        validate(stars);
        if (stars == 5) {
            throw new Exception("five star hotels need a manual review");
        }
        return stars + " stars";
    }

    public static void main(String[] args) {
        try {
            System.out.println(label(5));
        } catch (Exception e) {
            System.out.println(e.getMessage());
        }
    }
}

// Checked: the caller must decide what to do with a bad row.
class InvalidBookingException extends Exception {
    private final int lineNumber;
    private final String rawLine;

    InvalidBookingException(int lineNumber, String rawLine, String message) {
        super("line " + lineNumber + ": " + message);
        this.lineNumber = lineNumber;
        this.rawLine = rawLine;
    }

    InvalidBookingException(int lineNumber, String rawLine, String message, Throwable cause) {
        super("line " + lineNumber + ": " + message, cause);
        this.lineNumber = lineNumber;
        this.rawLine = rawLine;
    }

    int lineNumber() {
        return lineNumber;
    }

    String rawLine() {
        return rawLine;
    }
}

class Importer {
    static void parse(String line) throws InvalidBookingException {
        if (!line.contains(",")) {
            throw new InvalidBookingException(7, line, "missing separator");
        }
    }

    public static void main(String[] args) {
        try {
            parse("broken row");
        } catch (InvalidBookingException e) {
            System.out.println(e.getMessage());
            System.out.println("raw: " + e.rawLine());
        }
    }
}

